        @media (max-width: 480px) { .emoji-grid { grid-template-columns: repeat(6, 1fr); } #emojiBtn { width: 44px; height: 44px; } }
        :root { --accent: #ff3b5c; --accent2: #ff7a45; --card: #ffffff; --bg: #f2f3f7; --text: #1f2329; --muted: #8a9099; }
        html, body { background: var(--bg) !important; color: var(--text); }
        .app-container { padding-left: 10px !important; padding-right: 10px !important; }
        .live-section { border: none !important; box-shadow: none !important; background: transparent !important; overflow: visible !important; }
        .live-header { padding: 10px 14px !important; border-radius: 14px; background: var(--card); border: none; box-shadow: 0 4px 16px rgba(0,0,0,0.06); gap: 12px; }
