        .selector-btn, .control-btn { border-radius: 10px !important; backdrop-filter: blur(6px); }
        .chat-section { border: none !important; box-shadow: 0 4px 16px rgba(0,0,0,0.06) !important; background: var(--card) !important; border-radius: 14px !important; padding: 10px 10px 6px !important; }
