            .selector-menu { bottom: 36px; }
        }
    </style>
<body>
    <div id="config" style="display:none;">
        <div id="liveData" style="display:none;">__LIVE_DATA__</div>
    </div>

    <div class="app-container">
        <div class="live-section">


            <div class="live-header">
