        </div>

        <div class="chat-section">
             <div class="chat-messages" id="chatContainer"></div>
        </div>
    </div>

    <div id="bottomBar">
        <button class="floating-button" id="floatingBtn" title="直播信息"><i class="fas fa-info"></i></button>
        <button id="favBtn" class="bar-btn" title="收藏"><i class="fas fa-heart"></i></button>
        <div id="chatbar"><input id="ci" placeholder="发送弹幕…" maxlength="200"><button id="emojiBtn" title="表情"><i class="fas fa-smile"></i></button><button id="cs">发送</button></div>
    </div>

    <div id="emojiPanel" class="emoji-panel">
        <div class="emoji-panel-head"><span>发送表情</span><button id="emojiClose" class="emoji-close">×</button></div>
