            </div>
            <div class="floating-info-item">
                <span class="floating-info-label" id="floatingTimeLabel">时间标签:</span>
                <span class="floating-info-value" id="floatingStatusTime">--</span>
            </div>
        </div>

        <div class="floating-info-section" id="floatingUserDescriptionSection">
            <div class="floating-info-section-title">
                <i class="fas fa-user-circle"></i> 主播介绍
            </div>
            <div class="floating-content" id="floatingUserDescription"></div>
        </div>

        <div class="floating-info-section" id="floatingGoalSection">
            <div class="floating-info-section-title">
                <i class="fas fa-bullseye"></i> 直播目标
            </div>
            <div class="floating-content" id="floatingGoalDescription"></div>
        </div>

        <div class="floating-info-section" id="floatingFanClubSection">
            <div class="floating-info-section-title">
                <i class="fas fa-users"></i> 粉丝团留言
            </div>
            <div class="floating-content" id="floatingFanClubDescription"></div>
        </div>

        <div class="floating-info-section">
            <div class="floating-info-section-title">
                <i class="fas fa-gift"></i> 打赏菜单
            </div>
            <div class="floating-price-list" id="floatingPriceList"></div>
        </div>

        <div class="floating-info-section">
            <div class="floating-info-section-title">
                <i class="fas fa-tv"></i> 播放设置
            </div>
            <div class="floating-info-item">
                <span class="floating-info-label">当前线路:</span>
                <span class="floating-info-value" id="floatingLine">线路1</span>
            </div>
            <div class="floating-info-item">
                <span class="floating-info-label">清晰度:</span>
                <span class="floating-info-value" id="floatingQuality">默认</span>
            </div>
        </div>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/dplayer@1.27.1/dist/DPlayer.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/hls.js@1.4.10/dist/hls.min.js"></script>
    <script defer src="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/js/all.min.js"></script>
    <script>
        const liveDataElement = document.getElementById('liveData');
        let liveData = {};

        if (liveDataElement.textContent) {
            try {
                liveData = JSON.parse(liveDataElement.textContent);
            } catch (e) {}
        }

        const chatContainer = document.getElementById('chatContainer');
        let chatWs = null; let __lastSendId = 0;

        function addSystemMessage(text) {
            const systemDiv = document.createElement('div');
            systemDiv.className = 'message-item system-message';
            systemDiv.textContent = text;
            chatContainer.appendChild(systemDiv);
            while (chatContainer.children.length > 300) {
                chatContainer.removeChild(chatContainer.firstElementChild);
            }
            chatContainer.scrollTop = chatContainer.scrollHeight;
        }

        function initChat() {
            if (!liveData.modelId || !liveData.websocketUrl || !liveData.websocketToken) return;

            addSystemMessage('开始连接弹幕服务器');

            const timeoutMs = 10000;
            let connectTimeoutTimer = setTimeout(() => {
                if (chatWs && chatWs.readyState !== WebSocket.OPEN) {
                    chatWs.close();
                    addSystemMessage('连接超时：未能成功连接弹幕服务器');
                }
            }, timeoutMs);

            if (chatWs && chatWs.readyState === WebSocket.OPEN) {
                chatWs.close();
            }

            chatWs = new WebSocket(`${liveData.websocketUrl}`);
            window.__chatWs = chatWs;
            __lastSendId = 3;
            const sendQueue = [
                '{"connect":{"token":"' + liveData.websocketToken + '"},"id":1}',
                `{"subscribe":{"channel":"newChatMessage@${liveData.modelId}"},"id":2}`
            ];

            function getUserLevelTag(userData) {
                return userData?.userRanking?.level ? `<span class="level-tag">Lv.${userData.userRanking.level}</span>` : '';
            }

            const CHAT_EMOJI = {"grinning":"1f600","tongue":"1f61b","thumbsup":"1f44d","lol":"1f602","wink":"1f609","flirting":"1f618","inlove":"1f60d","heart":"2764-fe0f","flirt":"1f60f","ok":"1f44c","kissing":"1f617","airkiss":"1f618","cheekkiss":"1f619","flower":"1f337","behind":"1f351","blowjob":"1f4a6","onbed":"1f6cf-fe0f","ass":"1f351","movingboobs":"1f44c","wanker":"270a","crazyguy":"1f92a","ahh":"1f62e","devil":"1f608","dancing":"1f483","shy":"1f633","fire":"1f525","asking":"1f64f","angry":"1f620","facepalm":"1f926","cry":"1f622","sad":"1f61e","hideeyes":"1f648","king":"1f451","lgbt":"1f3f3-fe0f-200d-1f308","knight":"1f6e1-fe0f","gift":"1f381","please":"1f97a","bye":"1f44b"};
            const CHAT_EMOJI_RE = new RegExp(':(?:' + Object.keys(CHAT_EMOJI).join('|') + '):', 'g');
            function escapeHtml(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
            function renderChatText(s) { return escapeHtml(s).replace(CHAT_EMOJI_RE, function (mm) { const cp = CHAT_EMOJI[mm.slice(1, -1)]; if (!cp) return mm; const name = mm.slice(1, -1); return '<img class="chat-emoji-img" alt="' + name + '" src="https://cdn.jsdelivr.net/npm/emoji-datasource-apple@15.1.2/img/apple/64/' + cp + '.png">'; }); }

            function createMessageElement(data) {
                const messageDiv = document.createElement('div');
                messageDiv.className = 'message-item';

                const { type, userData, details } = data.message;
                const levelTag = getUserLevelTag(userData);

                let content = '';
                switch(type) {
                    case 'text':
                        messageDiv.className += ' text-item';
                        content = `${levelTag}<span class="user-name">${escapeHtml(userData.username)}</span>: ${renderChatText(details.body)}`;
                        break;
                    case 'tip':
                        messageDiv.className += ' tip-item';
                        content = `${levelTag}<span class="user-name">${escapeHtml(userData.username)}</span>: 已支付<span class="tip-amount">${details.amount}</span>代币${details.body ? ' · ' + renderChatText(details.body) : ''}`;
                        break;
                    case 'lovense':
                        messageDiv.className += ' lovense-item';
                        const { power, time, amount } = details.lovenseDetails.detail;
                        const powerText = power === 'low' ? '低' : power === 'medium' ? '中' : '高';
                        const clientLevelTag = getUserLevelTag(details.lovenseDetails.clientUserInfo);
                        content = `${clientLevelTag}<span class="user-name">${details.lovenseDetails.clientUserInfo.username}</span>: ${powerText}强度 · ${time}秒`;
                        break;
                    default:
                        return null;
                }

                messageDiv.innerHTML = content;
                return messageDiv;
            }

            function addMessageToPanel(messageData) {
                const messageElement = createMessageElement(messageData);
                if (messageElement) {
                    const messageWrapper = document.createElement('div');
                    messageWrapper.className = 'message-wrapper';
                    messageWrapper.appendChild(messageElement);
                    const nearBottom = chatContainer.scrollHeight - chatContainer.scrollTop - chatContainer.clientHeight < 90;
                    chatContainer.appendChild(messageWrapper);
                    while (chatContainer.children.length > 300) {
                        chatContainer.removeChild(chatContainer.firstElementChild);
                    }
                    if (nearBottom) chatContainer.scrollTop = chatContainer.scrollHeight;
                }
            }

            if (!window.__historyLoaded) {
                window.__historyLoaded = true;
                fetch('/api/front/v2/models/' + liveData.modelId + '/chat?limit=50', { credentials: 'include' })
                    .then(r => r.json())
                    .then(j => { ((j && j.messages) || []).forEach(mm => { try { addMessageToPanel({ message: mm }); } catch (e) {} }); })
                    .catch(() => {});
            }

            chatWs.onopen = () => {
                clearTimeout(connectTimeoutTimer);
                sendQueue.forEach(cmd => chatWs.send(cmd));
                addSystemMessage('弹幕服务器连接正常');
            };

            chatWs.onmessage = (e) => {
                if (e.data.trim() === '{}') {
                    chatWs.send('{}');
                    return;
                }
                try {
                    const data = JSON.parse(e.data);
                    if (data.ping) {
                        chatWs.send(JSON.stringify({ pong: data.ping }));
                    }
                    if (data.id === __lastSendId) {
                        if (data.error) { addSystemMessage('发送失败：' + (data.error.message || data.error.code)); }
                        else { addSystemMessage('发送成功'); }
                    }
                    if (data.push?.channel === `newChatMessage@${liveData.modelId}`) {
                        addMessageToPanel(data.push.pub.data);
                    }
                } catch (error) {}
            };

            chatWs.onerror = (err) => {
                const errorDiv = document.createElement('div');
                errorDiv.className = 'message-item system-message';
                errorDiv.textContent = '连接错误';
                chatContainer.appendChild(errorDiv);
                chatContainer.scrollTop = chatContainer.scrollHeight;
            };

            chatWs.onclose = (e) => {
                const closeDiv = document.createElement('div');
                closeDiv.className = 'message-item system-message';
                closeDiv.textContent = `连接关闭 | 错误码: ${e.code}`;
                chatContainer.appendChild(closeDiv);
                chatContainer.scrollTop = chatContainer.scrollHeight;
            };
        }

        const elements = {
            avatarImg: document.getElementById('avatarImg'),
            hostName: document.getElementById('hostName'),
            refreshBtn: document.getElementById('refreshBtn'),
            volumeBtn: document.getElementById('volumeBtn'),
            lineBtn: document.getElementById('lineBtn'),
            lineMenu: document.getElementById('lineMenu'),
            qualityBtn: document.getElementById('qualityBtn'),
            qualityMenu: document.getElementById('qualityMenu'),
            fullscreenBtn: document.getElementById('fullscreenBtn'),
            loadingIndicator: document.getElementById('loadingIndicator'),
            playerContainer: document.getElementById('playerContainer'),
            membersCount: document.getElementById('membersCount'),
            floatingBtn: document.getElementById('floatingBtn'),
            floatingPanel: document.getElementById('floatingPanel'),
            floatingHostName: document.getElementById('floatingHostName'),
            floatingTopBestPlace: document.getElementById('floatingTopBestPlace'),
            floatingMembersCount: document.getElementById('floatingMembersCount'),
            floatingTipMenuCreatedAt: document.getElementById('floatingTipMenuCreatedAt'),
            floatingTopic: document.getElementById('floatingTopic'),
            floatingTopicSection: document.getElementById('floatingTopicSection'),
            floatingGoalDescription: document.getElementById('floatingGoalDescription'),
            floatingGoalSection: document.getElementById('floatingGoalSection'),
            floatingUserDescription: document.getElementById('floatingUserDescription'),
            floatingUserDescriptionSection: document.getElementById('floatingUserDescriptionSection'),
            floatingFanClubDescription: document.getElementById('floatingFanClubDescription'),
            floatingFanClubSection: document.getElementById('floatingFanClubSection'),
            floatingPriceList: document.getElementById('floatingPriceList'),
            floatingDurationLabel: document.getElementById('floatingDurationLabel'),
            floatingDuration: document.getElementById('floatingDuration'),
            floatingTimeLabel: document.getElementById('floatingTimeLabel'),
            floatingStatusTime: document.getElementById('floatingStatusTime'),
            floatingLine: document.getElementById('floatingLine'),
            floatingQuality: document.getElementById('floatingQuality'),
            topicContainer: document.getElementById('topicContainer'),
            topic: document.getElementById('topic'),
            rotateBtn: document.getElementById('rotateBtn')
        };

        let dp = null;
        let isMuted = false;
        let isFullscreen = false;
        let hlsInstance = null;
        let durationInterval = null;
        let config = {};
        let hideControlsTimer = null;

        const getStreamUrl = (lineIndex = config.currentLine || 0, quality = config.currentQuality || 'auto') => {
            const line = config.hlsLines?.[lineIndex];
            if (!line || !config.stream) return '';

            const pureStatus = (config.status || '').toLowerCase();
            let suffix = '_auto';
            if (pureStatus !== 'public') suffix = '_160p_blurred';
            return `https://edge-hls.${line}/hls/${config.stream}/master/${config.stream}${suffix}.m3u8?pkey=bXorqTB5ZhP5FcpX`;
        };

        function getPresetUrl(quality) {
            const line = config.hlsLines && config.hlsLines[config.currentLine || 0];
            if (!line || !config.stream) return '';
            const pureStatus = (config.status || '').toLowerCase();
            let suffix = quality === 'auto' ? '_auto' : ('_' + quality);
            if (pureStatus !== 'public') suffix = '_160p_blurred';
            return `https://edge-hls.${line}/hls/${config.stream}/master/${config.stream}${suffix}.m3u8?pkey=bXorqTB5ZhP5FcpX`;
        }
        function showFreeze() {
            try {
                const v = dp && dp.video;
                if (!v || !v.videoWidth || v.readyState < 2) return;
                const cv = document.createElement('canvas');
                cv.width = v.videoWidth; cv.height = v.videoHeight;
                cv.getContext('2d').drawImage(v, 0, 0);
                const el = document.createElement('div');
                el.className = 'freeze-layer';
                el.style.backgroundImage = 'url(' + cv.toDataURL('image/jpeg', 0.7) + ')';
                elements.playerContainer.appendChild(el);
                window.__freezeEl = el;
                setTimeout(function(){ hideFreeze(); }, 9000);
            } catch (e) {}
        }
        function hideFreeze() {
            try { if (window.__freezeEl) { window.__freezeEl.remove(); window.__freezeEl = null; } } catch (e) {}
        }
        function reloadQuality(quality) {
            config.currentQuality = quality;
            const url = getPresetUrl(quality);
            if (!url) return;
            showFreeze();
            switchStream(url);
        }

        function seamlessQuality(quality, prevQuality) {
            try {
                if (!dp || !dp.video || !elements.playerContainer || config.isSwitching) return;
                const oldVideo = dp.video;
                const oldHls = hlsInstance;
                const url = getPresetUrl(quality);
                if (!url) return;
                config.isSwitching = true;
                try { elements.loadingIndicator.style.display = 'block'; } catch (e) {}

                const nv = document.createElement('video');
                nv.muted = true;
                nv.playsInline = true;
                nv.autoplay = true;
                nv.preload = 'auto';
                nv.setAttribute('playsinline', '');
                nv.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;object-fit:contain;z-index:900;opacity:0;transition:opacity .25s;background:#000;pointer-events:none;';
                elements.playerContainer.appendChild(nv);

                let finished = false;
                const cleanupOld = () => {
                    try { if (oldHls) oldHls.destroy(); } catch (e) {}
                    try { if (oldVideo && oldVideo.parentNode) oldVideo.parentNode.removeChild(oldVideo); } catch (e) {}
                };
                const fail = () => {
                    if (finished) return;
                    finished = true;
                    try { nv.remove(); } catch (e) {}
                    config.isSwitching = false;
                    config.currentQuality = prevQuality || 'auto';
                    try {
                        const disp = config.currentQuality === 'auto' ? '默认' : config.currentQuality;
                        elements.qualityBtn.innerHTML = disp + ' <i class="fas fa-chevron-down"></i>';
                        elements.floatingQuality.textContent = disp;
                        updateQualityMenuHighlights();
                    } catch (e) {}
                    try { elements.loadingIndicator.style.display = 'none'; } catch (e) {}
                    try { notify('清晰度切换失败，已保留原清晰度'); } catch (e) {}
                    try { oldVideo.muted = false; } catch (e) {}
                };

                const start = () => {
                    try {
                        const nh = new Hls({
                            enableWorker: true,
                            lowLatencyMode: true,
                            backBufferLength: 30,
                            maxBufferLength: 20,
                            liveSyncDurationCount: 3,
                            liveMaxLatencyDurationCount: 10,
                            maxLiveSyncPlaybackRate: 1.5
                        });
                        nh.loadSource(url);
                        nh.attachMedia(nv);
                        nh.on(Hls.Events.MANIFEST_PARSED, () => { try { nv.play(); } catch (e) {} });
                        nh.on(Hls.Events.ERROR, (ev, data) => { if (data && data.fatal) fail(); });

                        const ok = () => {
                            if (finished) return;
                            finished = true;
                            try {
                                const target = nh.liveSyncPosition;
                                if (target != null && Math.abs(nv.currentTime - target) > 0.5) nv.currentTime = target;
                            } catch (e) {}
                            // 音频无缝交接：保持用户当前静音状态
                            try {
                                const wasMuted = !!isMuted || !!oldVideo.muted;
                                nv.volume = oldVideo.volume;
                                nv.muted = wasMuted;
                                if (!wasMuted) { nv.muted = false; oldVideo.muted = true; }
                            } catch (e) {}
                            nv.style.opacity = '1';
                            try { oldVideo.style.transition = 'none'; oldVideo.style.opacity = '0'; oldVideo.style.visibility = 'hidden'; } catch (e) {}
                            setTimeout(() => {
                                cleanupOld();
                                dp.video = nv;
                                hlsInstance = nh;
                                try { bindVideoState(nv); } catch (e) {}
                                try { syncMuteUI(nv); } catch (e) {}
                                nv.addEventListener('click', function(e) { e.preventDefault(); e.stopPropagation(); return false; });
                                nv.addEventListener('playing', function(){ try { hideFreeze(); } catch (e) {} });
                                config.isSwitching = false;
                                try { elements.loadingIndicator.style.display = 'none'; } catch (e) {}
                                try { showControls(); } catch (e) {}
                            }, 120);
                        };
                        nv.addEventListener('playing', ok, { once: true });
                        setTimeout(() => { if (!finished) { try { nv.play(); } catch (e) {} } }, 1500);
                        setTimeout(() => { if (!finished) fail(); }, 9000);
                    } catch (e) { fail(); }
                };
                start();
            } catch (e) {
                try { config.isSwitching = false; } catch (x) {}
            }
        }

        function seamlessLine(lineIndex, oldLine) {
            try {
                if (!dp || !dp.video || !elements.playerContainer || config.isSwitching) return;
                const oldVideo = dp.video;
                const oldHls = hlsInstance;
                const url = getStreamUrl(lineIndex, config.currentQuality);
                if (!url) return;
                config.isSwitching = true;
                try { elements.loadingIndicator.style.display = 'block'; } catch (e) {}

                const nv = document.createElement('video');
                // 预加载期间静音，交接完成后再恢复用户音量状态
                nv.muted = true;
                nv.playsInline = true;
                nv.autoplay = false;
                nv.setAttribute('playsinline', '');
                nv.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;object-fit:contain;z-index:900;opacity:0;background:#000;pointer-events:none;';
                elements.playerContainer.appendChild(nv);

                let finished = false;
                const fail = () => {
                    if (finished) return;
                    finished = true;
                    try { nv.remove(); } catch (e) {}
                    config.isSwitching = false;
                    config.currentLine = oldLine;
                    try {
                        elements.lineBtn.innerHTML = '线路' + (oldLine + 1) + ' <i class="fas fa-chevron-down"></i>';
                        elements.floatingLine.textContent = '线路' + (oldLine + 1);
                        updateLineMenuHighlights();
                    } catch (e) {}
                    try { elements.loadingIndicator.style.display = 'none'; } catch (e) {}
                    try { notify('线路切换失败，已回退到原线路'); } catch (e) {}
                };
                const nh = new Hls({
                    enableWorker: true,
                    lowLatencyMode: true,
                    backBufferLength: 30,
                    maxBufferLength: 20,
                    liveSyncDurationCount: 3,
                    liveMaxLatencyDurationCount: 10,
                    maxLiveSyncPlaybackRate: 1.5
                });
                nh.loadSource(url);
                nh.attachMedia(nv);
                nh.on(Hls.Events.MANIFEST_PARSED, () => {
                    try { applyQuality(nh); } catch (e) {}
                    try { nv.play(); } catch (e) {}
                });
                nh.on(Hls.Events.ERROR, (ev, data) => { if (data && data.fatal) fail(); });
                nv.addEventListener('playing', () => {
                    if (finished) return;
                    finished = true;
                    try { if (oldHls) oldHls.destroy(); } catch (e) {}
                    try { if (oldVideo.parentNode) oldVideo.parentNode.removeChild(oldVideo); } catch (e) {}
                    nv.style.opacity = '1';
                    dp.video = nv;
                    hlsInstance = nh;
                    config.currentLine = lineIndex;
                    try { elements.lineBtn.innerHTML = '线路' + (lineIndex + 1) + ' <i class="fas fa-chevron-down"></i>'; elements.floatingLine.textContent = '线路' + (lineIndex + 1); updateLineMenuHighlights(); } catch (e) {}
                    try { nv.volume = oldVideo.volume; nv.muted = isMuted; if (!isMuted) nv.muted = false; bindVideoState(nv); syncMuteUI(nv); } catch (e) {}
                    config.isSwitching = false;
                    try { elements.loadingIndicator.style.display = 'none'; } catch (e) {}
                    try { showControls(); } catch (e) {}
                }, { once: true });
                setTimeout(() => { if (!finished) fail(); }, 9000);
            } catch (e) {
                try { config.isSwitching = false; } catch (x) {}
            }
        }

        function applyQuality(h) {
            const inst = h || hlsInstance;
            if (!inst || !inst.levels || !inst.levels.length) return;
            const q = config.currentQuality || 'auto';
            if (q === 'auto' || q === '160p_blurred') {
                try { inst.nextLevel = -1; inst.autoLevelCapping = -1; } catch (e) {}
                return;
            }
            const target = parseInt(String(q).replace(/[^0-9]/g, ''), 10);
            if (!target) return;
            const levels = inst.levels;
            const cur = (inst.currentLevel >= 0 && levels[inst.currentLevel]) || null;
            const curCodec = (cur && cur.attrs && cur.attrs.CODECS) || '';
            let exactName = -1, exactHeight = -1;
            let sameCodecBest = -1, sameCodecDiff = 1e9;
            let anyBest = -1, anyDiff = 1e9;
            for (let i = 0; i < levels.length; i++) {
                const lv = levels[i] || {};
                const attrs = lv.attrs || {};
                let hh = lv.height;
                if (!hh && attrs.RESOLUTION) hh = parseInt(String(attrs.RESOLUTION).split('x')[1], 10);
                if (!hh && !attrs.NAME) continue;
                const nm = attrs.NAME || '';
                const codec = attrs.CODECS || '';
                const diff = Math.abs((hh || 0) - target);
                if (diff < anyDiff) { anyDiff = diff; anyBest = i; }
                if (hh === target && exactHeight < 0) exactHeight = i;
                if (nm === q && exactName < 0) exactName = i;
                if (curCodec && codec && codec !== curCodec) continue;
                if (diff < sameCodecDiff) { sameCodecDiff = diff; sameCodecBest = i; }
            }
            let best = exactName;
            if (best < 0) best = exactHeight;
            if (best < 0) best = sameCodecBest;
            if (best < 0) best = anyBest;
            if (best >= 0) {
                window.__qBest = best;
                try { inst.nextLevel = best; inst.autoLevelCapping = best; } catch (e) {}
            }
        }

        function showControls() {
            elements.playerContainer.classList.remove('controls-hidden');
            elements.playerContainer.classList.add('controls-visible');
            if (hideControlsTimer) {
                clearTimeout(hideControlsTimer);
            }
            hideControlsTimer = setTimeout(() => {
                elements.playerContainer.classList.remove('controls-visible');
                elements.playerContainer.classList.add('controls-hidden');
            }, 3000);
        }

        function switchStream(url) {
            if (!dp || !dp.video || !url) return;

            config.isSwitching = true;
            elements.loadingIndicator.style.display = 'block';
            showControls();

            const video = dp.video;
            video.pause();
            video.src = '';
            video.load();

            if (hlsInstance) {
                try {
                    hlsInstance.stopLoad();
                    setTimeout(() => {
                        hlsInstance.destroy();
                        hlsInstance = null;
                        startNewStream(url, video);
                    }, 50);
                } catch (e) {
                    hlsInstance.destroy();
                    hlsInstance = null;
                    startNewStream(url, video);
                }
            } else {
                startNewStream(url, video);
            }
        }

        function startNewStream(url, video) {
            video.src = url;

            if (Hls.isSupported()) {
                hlsInstance = new Hls({
                    enableWorker: true,
                    lowLatencyMode: true,
                    backBufferLength: 30,
                    maxBufferLength: 20,
                    liveSyncDurationCount: 3,
                    liveMaxLatencyDurationCount: 10,
                    maxLiveSyncPlaybackRate: 1.5
                });

                hlsInstance.loadSource(url);
                hlsInstance.attachMedia(video);

                hlsInstance.on(Hls.Events.MANIFEST_PARSED, () => {
                    completeSwitch();
                    try { applyQuality(); } catch (e) {}
                    try { video.muted = isMuted; } catch (e) {}
                    try { syncMuteUI(video); } catch (e) {}
                    video.play().catch(function() {});
                });

                hlsInstance.on(Hls.Events.ERROR, (event, data) => {
                    if (data.fatal) {
                        switch(data.type) {
                            case Hls.ErrorTypes.NETWORK_ERROR:
                                hlsInstance.startLoad();
                                break;
                            case Hls.ErrorTypes.MEDIA_ERROR:
                                hlsInstance.recoverMediaError();
                                break;
                            default:
                                completeSwitch();
                                break;
                        }
                    }
                });

                setTimeout(() => {
                    if (config.isSwitching) {
                        completeSwitch();
                    }
                }, 5000);

            } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
                video.addEventListener('loadedmetadata', () => {
                    completeSwitch();
                    video.play().catch(e => {});
                });

                video.addEventListener('error', () => {
                    completeSwitch();
                });

                setTimeout(() => {
                    if (config.isSwitching) {
                        completeSwitch();
                    }
                }, 5000);
            } else {
                completeSwitch();
            }
        }

        function completeSwitch() {
            config.isSwitching = false;
            elements.loadingIndicator.style.display = 'none';
        }

        function togglePlayback() {
            try {
                if (!dp || !dp.video) return;
                const v = dp.video;
                // 直接使用原生 video 暂停/播放，绕过 DPlayer 内部状态
                if (v.paused) {
                    try { const p = v.play(); if (p && p.catch) p.catch(function(){}); } catch (e) {}
                } else {
                    try { v.pause(); } catch (e) {}
                    try { if (!v.paused) v.paused = true; } catch (e) {}
                }
            } catch (e) {}
            try { showControls(); } catch (e) {}
        }

        function syncMuteUI(v) {
            try {
                if (!v) return;
                const m = !!v.muted;
                isMuted = m;
                const btn = elements.volumeBtn;
                if (btn) btn.innerHTML = m ? '<i class="fas fa-volume-mute"></i>' : '<i class="fas fa-volume-up"></i>';
            } catch (e) {}
        }

        function notify(t) {
            try {
                const box = document.getElementById('chatContainer');
                if (!box) return;
                const d = document.createElement('div');
                d.className = 'message-item system-message';
                d.textContent = t;
                box.appendChild(d);
                box.scrollTop = box.scrollHeight;
            } catch (e) {}
        }

        function bindVideoState(v) {
            if (!v) return;
            const upd = function () {
                try {
                    const pc = elements.playerContainer;
                    if (!pc || !v) return;
                    if (v.paused) pc.classList.add('video-paused'); else pc.classList.remove('video-paused');
                    const btn = document.getElementById('centerPlayBtn');
                    if (btn) btn.innerHTML = v.paused ? '<i class="fas fa-play"></i>' : '<i class="fas fa-pause"></i>';
                    syncMuteUI(v);
                } catch (e) {}
            };
            v.addEventListener('play', upd);
            v.addEventListener('pause', upd);
            v.addEventListener('playing', upd);
            v.addEventListener('volumechange', function(){ syncMuteUI(v); });
            upd();
        }

        function initPlayer() {
            config = { ...liveData, currentLine: 0, currentQuality: 'auto', isSwitching: false };
            try { window.__fitAr = null; } catch (e) {}

            const url = getStreamUrl();
            if (!url) return;

            if (dp) {
                dp.destroy();
                dp = null;
            }

            dp = new DPlayer({
                container: document.getElementById('dplayer'),
                live: true,
                autoplay: true,
                theme: '#00a1d6',
                loop: false,
                lang: 'zh-cn',
                screenshot: false,
                hotkey: false,
                preload: 'auto',
                volume: 0.7,
                mutex: true,
                controls: false,
                video: {
                    url: url,
                    pic: config.coverImg,
                    type: 'customHls',
                    customType: {
                        customHls: function(video, player) {}
                    }
                },
                contextmenu: [],
                danmaku: false
            });

            dp.video.addEventListener('playing', function(){ try { hideFreeze(); } catch (e) {} });
            try { bindVideoState(dp.video); } catch (e) {}
            let prefMuted = false;
            try { const savedMute = localStorage.getItem('vt_muted'); if (savedMute === '0') prefMuted = false; } catch (e) {}
            dp.video.muted = prefMuted;
            isMuted = prefMuted;
            if (elements.volumeBtn) elements.volumeBtn.innerHTML = isMuted ? '<i class="fas fa-volume-mute"></i>' : '<i class="fas fa-volume-up"></i>';
            try { syncMuteUI(dp.video); } catch (e) {}
            try { var __pp = dp.video.play(); if (__pp && __pp.catch) __pp.catch(function(){}); } catch (e) {}
            try {
                const resumeAudio = function () {
                    try {
                        if (isMuted && dp && dp.video && localStorage.getItem('vt_muted') === '0') {
                            dp.video.muted = false;
                            isMuted = false;
                            if (elements.volumeBtn) elements.volumeBtn.innerHTML = '<i class="fas fa-volume-up"></i>';
                        }
                    } catch (e) {}
                    document.removeEventListener('pointerdown', resumeAudio);
                    document.removeEventListener('touchstart', resumeAudio);
                };
                document.addEventListener('pointerdown', resumeAudio, { once: true });
                document.addEventListener('touchstart', resumeAudio, { once: true });
            } catch (e) {}

            const videoElement = dp.video;
            if (videoElement) {
                videoElement.style.pointerEvents = 'none';
                videoElement.addEventListener('click', function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    return false;
                });
            }

            const dplayerContainer = dp.container;
            dplayerContainer.style.pointerEvents = 'none';
            dplayerContainer.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                return false;
            });

            isMuted = dp.video.muted;
            elements.volumeBtn.innerHTML = isMuted 
                ? '<i class="fas fa-volume-mute"></i>'
                : '<i class="fas fa-volume-up"></i>';

            switchStream(url);
        }

        function refreshPlayer() {
            if (config.isSwitching || !config.stream) return;
            const url = getStreamUrl(config.currentLine, config.currentQuality);
            switchStream(url);
        }

        function switchLine(lineIndex) {
            if (config.isSwitching || !config.hlsLines || lineIndex >= config.hlsLines.length) return;
            const oldLine = config.currentLine;
            config.currentLine = lineIndex;
            elements.lineBtn.innerHTML = `线路${lineIndex + 1} <i class="fas fa-chevron-down"></i>`;
            elements.floatingLine.textContent = `线路${lineIndex + 1}`;
            updateLineMenuHighlights();
            elements.lineMenu.style.display = 'none';

            if (dp && dp.video && hlsInstance) {
                seamlessLine(lineIndex, oldLine);
            } else {
                config.currentLine = lineIndex;
                const url = getStreamUrl(lineIndex, config.currentQuality);
                switchStream(url);
            }
        }

        function switchQuality(quality) {
            if (config.isSwitching) return;
            const prevQuality = config.currentQuality;
            config.currentQuality = quality;
            const displayText = quality === 'auto' ? '默认' : quality;
            elements.qualityBtn.innerHTML = `${displayText} <i class="fas fa-chevron-down"></i>`;
            elements.floatingQuality.textContent = displayText;
            updateQualityMenuHighlights();
            elements.qualityMenu.style.display = 'none';
            if (quality === 'auto') {
                if (hlsInstance) {
                    try { hlsInstance.nextLevel = -1; hlsInstance.autoLevelCapping = -1; } catch (e) {}
                } else {
                    seamlessQuality('auto');
                }
                return;
            }
            seamlessQuality(quality, prevQuality);
        }

        function formatDuration(seconds) {
            if (!seconds) return '0秒';

            const days = Math.floor(seconds / (24 * 60 * 60));
            const hours = Math.floor((seconds % (24 * 60 * 60)) / (60 * 60));
            const minutes = Math.floor((seconds % (60 * 60)) / 60);
            const secs = Math.floor(seconds % 60);

            let result = '';
            if (days > 0) result += `${days}天`;
            if (hours > 0) result += `${hours}小时`;
            if (minutes > 0) result += `${minutes}分钟`;
            if (secs > 0 || result === '') result += `${secs}秒`;

            return result;
        }

        function updateTimeInfo() {
            if (!config.status || !config.startTime) return;

            const pureStatus = config.status.replace(/^状态：/, '').toLowerCase();
            const isPublic = pureStatus === 'public';
            const startTime = config.startTime ? new Date(config.startTime).getTime() : null;
            const now = Date.now();

            if (config.isLive && startTime) {
                if (isPublic) {
                    elements.floatingDurationLabel.textContent = '直播时长:';
                    elements.floatingTimeLabel.textContent = '直播时间:';

                    const duration = Math.floor((now - startTime) / 1000);
                    const durationText = formatDuration(duration);
                    elements.floatingDuration.textContent = durationText;

                    const startDate = new Date(startTime);
                    elements.floatingStatusTime.textContent = startDate.toLocaleString();
                } else {
                    elements.floatingDurationLabel.textContent = '持续时长:';
                    elements.floatingTimeLabel.textContent = '私密直播:';

                    const duration = Math.floor((now - startTime) / 1000);
                    const durationText = formatDuration(duration);
                    elements.floatingDuration.textContent = durationText;

                    const startDate = new Date(startTime);
                    elements.floatingStatusTime.textContent = startDate.toLocaleString();
                }
            } else if (startTime) {
                elements.floatingDurationLabel.textContent = '持续时长:';
                elements.floatingTimeLabel.textContent = '下播时间:';

                const duration = Math.floor((now - startTime) / 1000);
                let durationText = formatDuration(duration);
                elements.floatingDuration.textContent = durationText;

                const endDate = new Date(startTime);
                elements.floatingStatusTime.textContent = endDate.toLocaleString();
            } else {
                elements.floatingDuration.textContent = '--';
                elements.floatingStatusTime.textContent = '--';
            }
        }

        function startDurationUpdate() {
            if (durationInterval) {
                clearInterval(durationInterval);
            }

            updateTimeInfo();
            durationInterval = setInterval(updateTimeInfo, 1000);
        }

        function updateFloatingPanel() {
            const pureUsername = (config.username || '').split('/').pop() || config.username || '';
            elements.floatingHostName.textContent = pureUsername || '未知主播';
            elements.membersCount.textContent = config.membersCount > 0 ? config.membersCount.toLocaleString() : '--';
            elements.floatingMembersCount.textContent = config.membersCount > 0 ? config.membersCount.toLocaleString() : '--';

            if (config.topBestPlace > 0) {
                const rankText = `TOP ${config.topBestPlace}`;
                elements.floatingTopBestPlace.textContent = rankText;
            } else {
                elements.floatingTopBestPlace.textContent = '未上榜';
            }

            if (config.tipMenuCreatedAt) {
                const createdAt = new Date(config.tipMenuCreatedAt);
                elements.floatingTipMenuCreatedAt.textContent = createdAt.toLocaleString();
            } else {
                elements.floatingTipMenuCreatedAt.textContent = '--';
            }

            if (config.topic && String(config.topic).trim() !== '') {
                elements.floatingTopic.textContent = config.topic;
                elements.floatingTopicSection.style.display = 'block';
            } else {
