(function(){
  try{
    var ev=String(event||'');
    if(ev!=='addBookShelf' && ev!=='delBookShelf') return true;
    var m=String((book&&book.bookUrl)||'').match(/models\/(\d+)/);
    var id=m?m[1]:'';
    if(!id) return true;
    var ck=String(cookie.getCookie('https://zh.virtualtaboo.live/')||'');
    if(!ck) return true;
    var cfg=JSON.parse(String(java.ajax('https://zh.virtualtaboo.live/api/front/v3/config/initial-dynamic')));
    var d=(cfg&&cfg.initialDynamic)||{};
    var uid=(d.user&&d.user.id)||'';
    if(!uid) return true;
    var csrf=d.csrfToken||'',ts=d.csrfTimestamp||'',nt=d.csrfNotifyTimestamp||'';
    var body=JSON.stringify({csrfToken:csrf,csrfTimestamp:ts,csrfNotifyTimestamp:nt,uniq:'u'+Date.now()});
    var client=new Packages.okhttp3.OkHttpClient();
    var mt=Packages.okhttp3.MediaType.parse('application/json');
    var rb=Packages.okhttp3.RequestBody.create(mt,body);
    var builder=new Packages.okhttp3.Request.Builder()
      .url('https://zh.virtualtaboo.live/api/front/users/'+uid+'/favorites/'+id)
      .addHeader('Cookie',ck)
      .addHeader('Accept','application/json')
      .addHeader('User-Agent','Mozilla/5.0 (Linux; Android 13) Chrome/120 Mobile');
    if(ev==='addBookShelf'){ builder.put(rb); }
    else { builder.delete(rb); }
    var resp=client.newCall(builder.build()).execute();
    if(resp.code()===200){ java.toast(ev==='addBookShelf'?'已同步到站点收藏':'已取消站点收藏'); }
    else { java.toast('收藏同步失败('+resp.code()+')'); }
  }catch(e){ try{java.toast('收藏同步异常：'+e);}catch(x){} }
  return true;
})()

