        /* ===== 播放器固定顶栏 ===== */
        #playerContainer { position: fixed !important; top: 0; left: 50% !important; right: auto !important; transform: translateX(-50%); width: 100% !important; max-width: 1200px; z-index: 1500; border-radius: 0 !important; aspect-ratio: 16/9; min-height: 140px; }
        #playerContainer:fullscreen, #playerContainer:-webkit-full-screen { left: 0 !important; transform: none !important; max-width: none !important; width: 100vw !important; }
        .app-container { padding-top: min(56.25vw, 75vh); }
