        /* ===== 表情面板 ===== */
        #emojiBtn { flex: 0 0 auto; width: 42px; height: 42px; border: none; border-radius: 50%; background: #f2f3f7; color: #ff3b5c; font-size: 19px; display: flex; align-items: center; justify-content: center; cursor: pointer; margin: 0; padding: 0; }
        #emojiBtn:active { background: #ffe3e8; }
        .emoji-panel { position: fixed; left: 50%; transform: translateX(-50%); bottom: calc(58px + env(safe-area-inset-bottom)); width: 100%; max-width: 1200px; max-height: 45vh; background: #fff; border-radius: 14px 14px 0 0; box-shadow: 0 -8px 24px rgba(0,0,0,0.16); z-index: 2500; display: none; flex-direction: column; overflow: hidden; }
        .emoji-panel.open { display: flex; }
        .emoji-panel-head { flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; padding: 10px 14px; font-size: 14px; font-weight: 700; color: #1f2329; border-bottom: 1px solid #eee; }
        .emoji-close { border: none; background: transparent; font-size: 22px; line-height: 1; color: #8a9099; cursor: pointer; padding: 0 4px; }
        .emoji-grid { flex: 1 1 auto; display: grid; grid-template-columns: repeat(8, 1fr); gap: 6px; padding: 10px; overflow-y: auto; }
        .emoji-item { display: flex; align-items: center; justify-content: center; height: 42px; border: none; background: transparent; border-radius: 10px; cursor: pointer; padding: 0; -webkit-tap-highlight-color: transparent; }
        .emoji-item:active { background: #f2f3f7; }
