            <div class="player-container" id="playerContainer">
                <div id="dplayer"></div>
                <button id="centerPlayBtn" class="center-play-btn" title="播放/暂停"><i class="fas fa-play"></i></button>
                <div class="loading-indicator" id="loadingIndicator">正在切换...</div>
                <div class="custom-controls">
                    <div class="left-controls">
                        <button class="control-btn" id="refreshBtn" title="刷新播放">
