                item.className = 'menu-item';
                item.textContent = '无线路';
                item.style.opacity = '0.6';
                elements.lineMenu.appendChild(item);
                return;
            }

            config.hlsLines.forEach((line, index) => {
                const item = document.createElement('div');
                item.className = `menu-item ${index === config.currentLine ? 'active' : ''}`;
                item.textContent = `线路${index + 1}`;
                item.dataset.index = index;
                item.onclick = (e) => {
                    e.stopPropagation();
                    switchLine(index);
                };
                elements.lineMenu.appendChild(item);
            });
        }

        function initQualityMenu() {
            elements.qualityMenu.innerHTML = '';
            const pureStatus = (config.status || '').replace(/^状态：/, '').toLowerCase();

            let availableQualities = [];
            availableQualities.push({ value: 'auto', display: '默认' });

            if (pureStatus !== 'public') {
                availableQualities = [{ value: '160p_blurred', display: '模糊' }];
                config.currentQuality = '160p_blurred';
            } else if (config.pixelatedResolutions && config.pixelatedResolutions.length > 0) {
                config.pixelatedResolutions.forEach(resolution => {
                    if (resolution !== '160p_blurred') {
                        availableQualities.push({ 
                            value: resolution, 
                            display: resolution 
                        });
                    }
                });
            }

            availableQualities.forEach((quality) => {
                const isActive = quality.value === config.currentQuality;
                const item = document.createElement('div');
                item.className = `menu-item ${isActive ? 'active' : ''}`;
                item.textContent = quality.display;
                item.dataset.quality = quality.value;
                item.onclick = (e) => {
                    e.stopPropagation();
                    switchQuality(quality.value);
                };
                elements.qualityMenu.appendChild(item);
            });

            const currentQuality = availableQualities.find(q => q.value === config.currentQuality);
            const displayText = currentQuality ? currentQuality.display : '默认';
            elements.qualityBtn.innerHTML = `${displayText} <i class="fas fa-chevron-down"></i>`;
            elements.floatingQuality.textContent = displayText;
        }

        function updateLineMenuHighlights() {
            const items = elements.lineMenu.querySelectorAll('.menu-item');
            items.forEach((item, index) => {
                if (index === config.currentLine) {
                    item.classList.add('active');
                } else {
                    item.classList.remove('active');
                }
            });
        }

        function updateQualityMenuHighlights() {
            const items = elements.qualityMenu.querySelectorAll('.menu-item');
            items.forEach((item) => {
                const quality = item.dataset.quality;
                if (quality === config.currentQuality) {
                    item.classList.add('active');
                } else {
                    item.classList.remove('active');
                }
            });
        }

        async function handleRotateClick() {
            try {
                if (!document.fullscreenElement) {
                    await elements.playerContainer.requestFullscreen();
                }

                if (screen.orientation) {
                    const type = screen.orientation.type;
                    if (type.startsWith('portrait')) {
                        await screen.orientation.lock('landscape');
                        elements.rotateBtn.textContent = '横屏';
                    } else {
                        await screen.orientation.lock('portrait');
                        elements.rotateBtn.textContent = '横屏';
                    }
                }
                showControls();
            } catch (err) {}
        }

        function bindEvents() {
            elements.refreshBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                refreshPlayer();
                showControls();
            });

            elements.volumeBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                if (dp && dp.video && !config.isSwitching) {
                    isMuted = !isMuted;
                    dp.video.muted = isMuted;
                    elements.volumeBtn.innerHTML = isMuted 
                        ? '<i class="fas fa-volume-mute"></i>'
                        : '<i class="fas fa-volume-up"></i>';
                }
                showControls();
            });

            elements.fullscreenBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                if (!isFullscreen) {
                    const container = document.querySelector('.player-container');
                    if (container.requestFullscreen) {
                        container.requestFullscreen();
                    } else if (container.webkitRequestFullscreen) {
                        container.webkitRequestFullscreen();
                    }
                    elements.fullscreenBtn.innerHTML = '<i class="fas fa-compress"></i>';
                } else {
                    if (document.exitFullscreen) {
                        document.exitFullscreen();
                    } else if (document.webkitExitFullscreen) {
                        document.webkitExitFullscreen();
                    }
                    elements.fullscreenBtn.innerHTML = '<i class="fas fa-expand"></i>';
                }
                isFullscreen = !isFullscreen;
                showControls();
            });

            elements.lineBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                elements.lineMenu.style.display = 
                    elements.lineMenu.style.display === 'block' ? 'none' : 'block';
                elements.qualityMenu.style.display = 'none';
                updateLineMenuHighlights();
                showControls();
            });

            elements.qualityBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                elements.qualityMenu.style.display = 
                    elements.qualityMenu.style.display === 'block' ? 'none' : 'block';
                elements.lineMenu.style.display = 'none';
                updateQualityMenuHighlights();
                showControls();
            });

            elements.rotateBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                handleRotateClick();
            });

            elements.playerContainer.addEventListener('touchstart', (e) => {
                if (e.target.closest('.custom-controls, .selector-menu, .control-btn, .selector-btn, .menu-item, .rotate-btn')) {
                    showControls();
                    return;
                }

                if (elements.playerContainer.classList.contains('controls-hidden')) {
                    showControls();
                } else {
                    elements.playerContainer.classList.remove('controls-visible');
                    elements.playerContainer.classList.add('controls-hidden');
                    if (hideControlsTimer) {
                        clearTimeout(hideControlsTimer);
                        hideControlsTimer = null;
                    }
                }
            });

            document.addEventListener('click', (e) => {
                if (!e.target.closest('.selector-btn')) {
                    elements.lineMenu.style.display = 'none';
                    elements.qualityMenu.style.display = 'none';
                }
            });

            document.addEventListener('fullscreenchange', handleFullscreenChange);
            document.addEventListener('webkitfullscreenchange', handleFullscreenChange);

            elements.floatingBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                elements.floatingPanel.style.display = 
                    elements.floatingPanel.style.display === 'block' ? 'none' : 'block';
            });

            document.addEventListener('click', (e) => {
                if (!e.target.closest('.floating-button') && !e.target.closest('.floating-panel')) {
                    elements.floatingPanel.style.display = 'none';
                }
            });
        }

        function handleFullscreenChange() {
            const isFullscreenNow = !!(document.fullscreenElement || 
                document.webkitFullscreenElement);
            if (!isFullscreenNow) {
                elements.fullscreenBtn.innerHTML = '<i class="fas fa-expand"></i>';
                isFullscreen = false;
            }
        }

        function initializeApp() {
            if (!liveData || Object.keys(liveData).length === 0) return;

